///
/// \file variableinfo.h
/// \brief Declares the description of a simulated OPC UA variable.
///

#pragma once

#include <QString>
#include <QStringList>
#include <QVariant>

///
/// \brief Waveform or sequence the simulator generates for a variable.
///
enum class SimulationFunction { None, Sine, Square, Triangle, Ramp, Random, Step, Toggle, Counter, List };

///
/// \brief How a variable value is generated by the simulator.
///
struct SimulationSettings
{
    /// \brief Waveform; None leaves the value untouched.
    SimulationFunction function = SimulationFunction::None;
    /// \brief Update interval in milliseconds.
    int intervalMs = 1000;
    /// \brief Length of one waveform cycle in milliseconds.
    int periodMs = 10000;
    /// \brief Peak deviation from the offset.
    double amplitude = 0.0;
    /// \brief Centre value of the generated signal.
    double offset = 0.0;
    /// \brief Values List cycles through, as text of the variable's data type.
    QStringList values;
};

///
/// \brief Describes one variable of an object in the address space.
///
struct VariableInfo
{
    ///
    /// \brief OPC UA value quality.
    ///
    enum class Quality { Good, Uncertain, Bad };

    /// \brief String form of the node identifier.
    QString nodeId;
    /// \brief Display name.
    QString displayName;
    /// \brief Resource name of the icon.
    QString icon;
    /// \brief Current value.
    QVariant value;
    /// \brief Built-in data type name.
    QString dataType;
    /// \brief Access level text: "Read", "Write" or "Read/Write".
    QString access;
    /// \brief Quality of the current value.
    Quality quality = Quality::Good;
    /// \brief Value the variable starts with; text typed by the user until it is parsed.
    QVariant initialValue;
    /// \brief Quality the server reports with every value of the variable.
    Quality configuredQuality = Quality::Good;
    /// \brief Simulation that drives the value.
    SimulationSettings simulation;
    /// \brief Whether the variable comes from an imported model, whose properties cannot be edited.
    bool readOnly = false;
};
